        rem = qty
        while rem > 0:
            take = min(rem, max_parcel_grams // w)
            items.append((str(cid), take * w))
            chunk_info[str(cid)] = (sku, take)
            cid += 1
            rem -= take
    bins = first_fit_decreasing(items, max_parcel_grams)
    res = []
    for b in bins:
        p = {}
        for cid, _ in b:
            sku, q = chunk_info[cid]
            p[sku] = p.get(sku, 0) + q
        res.append(p)
