from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from stockflow.parse_movement_line import parse_movement_line


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    on_hand: Dict[str, int] = {}
    last_shp: Dict[str, int] = {}

    for line in lines:
        s = line.strip()
        if not s or s.startswith('#'):
            continue

        r = parse_movement_line(line, case_sizes)
        d, sku, q, t = r['day'], r['sku'], r['qty'], r['type']

        # On-hand is calculated only up to 'today'
        if d <= today:
            on_hand[sku] = on_hand.get(sku, 0) + q
            if t == 'SHP':
                if sku not in last_shp or d > last_shp[sku]:
                    last_shp[sku] = d

    res = []
    for sku, qty in on_hand.items():
        if qty > 0:
            # If no SHP found on or before today, it's dead stock.
            # If SHP found, check if it's old enough.
            if sku not in last_shp or (today - last_shp[sku] >= idle_days):
                res.append(sku)

    return sorted(res)"
